#!/usr/bin/env python3
"""Build the administrator/faculty/course-lead hub, request draft and pilot packet."""
import csv
import html
import json
import re
from pathlib import Path

ROOT=Path(__file__).resolve().parent.parent
DEST=ROOT/'docs/education-compute'
OUT=ROOT/'output/education-compute'
ESC=html.escape
MARKER='\n\nCLOUDBANK REQUEST AND TWO-COURSE PILOT | October 12, 2026\n'
NAV=[('program.html','Overview'),('pilot-plan.html','Pilot plan'),('budget.html','Budget'),('access-request.html','ACCESS draft'),('readiness.html','Pre-class checks'),('resource-library.html','Library'),('index.html','Talk')]


def request_text(p):
    r=p['request']
    fields=[('Status',r['status']),('Project title',r['title']),('Opportunity / resource',r['opportunity']+' / '+r['resource']),('Intended use',r['use']),('Institution',r['institution']),('PI',r['pi']),('Co-PIs',r['co_pis']),('Project dates',r['dates']),('Course titles',p['courses'][0]['title']+'; '+p['courses'][1]['title']),('Enrollment',r['students']),('Staff accounts',r['staff']),('Keywords',r['keywords']),('Field of science',r['field']),('Supporting grant',r['grant']),('Public overview',r['public_overview']),('Planned work summary',r['summary']),('Resource justification / amount',r['resource_justification']),('Software and assignments',r['requested_software']),('Other available resources',r['other_resources'])]
    return '\n\n'.join(k.upper()+'\n'+v for k,v in fields)+'\n\nREQUIRED COMPLETION / ATTACHMENTS\n'+'\n'.join('- '+x for x in r['attachments'])+'\n\nREVIEW AND SUBMISSION STEPS\n'+'\n'.join(str(i+1)+'. '+x for i,x in enumerate(r['submission_steps']))+'\n\nPROVIDER QUESTIONS (NOT SENT)\n'+'\n'.join('- '+x for x in r['provider_questions'])+'\n'


def chrome(text,name):
    if name=='index.html':return text
    text=re.sub(r'<!-- program-chrome-start -->.*?<!-- program-chrome-end -->','',text,flags=re.S)
    active=name if name in [n for n,_ in NAV] else 'resource-library.html'
    nav=''.join('<a href="'+n+'"'+(' aria-current="page"' if n==active else '')+'>'+label+'</a>' for n,label in NAV)
    header='<!-- program-chrome-start --><a class="program-skip" href="#program-content">Skip to content</a><header class="program-header"><div class="program-top"><a class="program-brand" href="program.html">Computing for teaching<small>UArizona Information Science · planning proposal</small></a><span class="program-pill">Discussion draft</span></div><nav class="program-nav" aria-label="Program navigation">'+nav+'</nav></header><!-- program-chrome-end -->'
    text=text.replace('</head>','<!-- program-chrome-start --><link rel="stylesheet" href="program.css"><!-- program-chrome-end --></head>')
    text=text.replace('<body>','<body>'+header)
    text=re.sub(r'<main(?![^>]*\bid=)', '<main id="program-content"',text,count=1)
    footer='<!-- program-chrome-start --><footer class="program-footer"><p><strong>Proposal, not a service announcement.</strong> No CloudBank request, allocation, staffing appointment or pilot budget is approved by this site. Provider policies and proposed tests are separate from completed classroom evidence.</p><p><a href="program.html">Program overview</a> · <a href="resource-library.html">All resources and downloads</a> · <a href="evidence.html">Source ledger</a> · <a href="index.html">Five-slide talk</a></p><p>Prepared for discussion by Greg Chism · Checked October 12, 2026 · Course/term placeholders require completion. This site contains no student records or approval workflow.</p></footer><script src="program.js"></script><!-- program-chrome-end -->'
    return text.replace('</body>',footer+'</body>')


def build():
    p=json.loads((ROOT/'site/education-compute-pilot.json').read_text());d=json.loads((DEST/'evidence.json').read_text());e=d['evidence'];b=p['budget']
    def refs(keys):return ' · '.join('<a href="evidence.html#'+ESC(k)+'">'+ESC(e[k]['title'])+'</a>' for k in keys)
    def links(rows):return '<div class="pg-actions">'+''.join('<a class="pg-link" href="'+ESC(url,quote=True)+'">'+ESC(label)+' ↗</a>' for label,url in rows)+'</div>'
    def page(title,body):
        base='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'''+ESC(title)+''' · Computing for teaching</title><meta name="description" content="A proposed UArizona data science and MLIS classroom pilot: request draft, staffing, budget, readiness and evidence."><link rel="icon" href="../assets/favicons/talk.svg" type="image/svg+xml"><link rel="icon" href="../assets/favicons/talk-32.png" type="image/png" sizes="32x32"><link rel="apple-touch-icon" href="../assets/favicons/talk-180.png" sizes="180x180"></head><body><main class="program-main" id="program-content">'''+body+'''</main><script>window.programData='''+json.dumps(p,ensure_ascii=False).replace('<','\\u003c')+'''</script></body></html>'''
        return base
    visual='''<figure class="pg-visual"><svg viewBox="0 0 450 330" role="img" aria-label="Proposed service: approved ACCESS resources feed CPU classrooms for data science and MLIS, with funded local support, backups and exports"><defs><marker id="arrow" viewBox="0 0 10 10" refX="7" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="#99bfc9"/></marker></defs><rect x="85" y="10" width="280" height="60" rx="9" fill="#36526f"/><text x="225" y="36" text-anchor="middle" fill="#fff" font-size="18" font-weight="600">Approved ACCESS resource</text><text x="225" y="57" text-anchor="middle" fill="#d2e6ed" font-size="13">CloudBank managed CPU Classroom</text><path d="M225 70V91M225 91H110V112M225 91H340V112" fill="none" stroke="#99bfc9" stroke-width="2" marker-end="url(#arrow)"/><rect x="10" y="118" width="200" height="90" rx="9" fill="#eef4f0"/><rect x="240" y="118" width="200" height="90" rx="9" fill="#eef4f0"/><text x="110" y="146" text-anchor="middle" fill="#243d45" font-size="19" font-weight="600">Data science</text><text x="110" y="170" text-anchor="middle" fill="#243d45" font-size="14">40 planned students</text><text x="110" y="193" text-anchor="middle" fill="#4b6668" font-size="12">Notebooks · small CPU models</text><text x="340" y="146" text-anchor="middle" fill="#243d45" font-size="19" font-weight="600">MLIS</text><text x="340" y="170" text-anchor="middle" fill="#243d45" font-size="14">40 planned students</text><text x="340" y="193" text-anchor="middle" fill="#4b6668" font-size="12">Metadata · queries · provenance</text><path d="M110 208V233H340V208M225 233V252" fill="none" stroke="#99bfc9" stroke-width="2" marker-end="url(#arrow)"/><rect x="10" y="259" width="430" height="66" rx="9" fill="#ad874b"/><text x="225" y="285" text-anchor="middle" fill="#fff" font-size="18" font-weight="650">Fund the service around the compute</text><text x="225" y="309" text-anchor="middle" fill="#fff" font-size="13">People · support · backup · restore · export</text></svg><figcaption>Proposed architecture. Approval and classroom readiness still need evidence.</figcaption></figure>'''
    panels=''.join('<article class="pg-audience-panel" data-audience-panel="'+a['id']+'"'+(' hidden' if a['id']!='administrators' else '')+'><p class="pg-kicker">'+ESC(a['name'])+'</p><h3>'+ESC(a['headline'])+'</h3><p>'+ESC(a['body'])+'</p>'+links(a['links'])+'</article>' for a in p['audiences'])
    tabs='<div class="pg-tabs" role="group" aria-label="Choose an audience">'+''.join('<button type="button" data-audience="'+a['id']+'" aria-pressed="'+str(a['id']=='administrators').lower()+'">'+ESC(a['name'])+'</button>' for a in p['audiences'])+'</div>'
    timeline='<ol class="pg-timeline">'+''.join('<li><p class="pg-kicker">'+ESC(ph['when'])+'</p><h3>'+ESC(ph['title'])+'</h3></li>' for ph in p['phases'])+'</ol>'
    overview='''<div class="pg-hero"><div><p class="pg-kicker">A decision brief for administrators, faculty and course leads</p><h1>Reliable computing<br>for teaching.</h1><p class="pg-lead">'''+ESC(p['core_statement'])+'''. Build a service that can carry a course through setup, teaching and export.</p>'''+links([('Review the pilot','pilot-plan.html'),('CloudBank request draft','access-request.html')])+'''<p class="pg-small">Discussion draft · 12 October 2026 · No award or institutional commitment claimed.</p></div>'''+visual+'''</div><div class="pg-metrics"><div><strong>80 students</strong><span>Two representative 40-seat courses</span></div><div><strong>23 weeks</strong><span>Six prep + fifteen teaching + two close-out</span></div><div><strong>$30,000</strong><span>Illustrative staged cash ceiling; staff time also required</span></div></div><p class="pg-note">'''+ESC(p['decision'])+'''</p><section><h2>Start with the decision you own</h2>'''+tabs+panels+'''</section><section><p class="pg-kicker">One pilot, five stages</p><h2>Prove a component before a semester.</h2>'''+timeline+links([('Schedule, course activities and responsibilities','pilot-plan.html')])+'''</section><section><h2>The proposal in three commitments</h2><div class="pg-grid three"><article class="pg-card"><h3>Keep required work on CPU</h3><p>Reproducible DS notebooks and MLIS metadata/database exercises. GPUs, MESA and throughput pools are optional modules with their own gates.</p></article><article class="pg-card"><h3>Pay for continuity</h3><p>Named primary and backup operators, course help, approved data destinations, independent restores and usable exports. Resource approval does not fund these duties.</p></article><article class="pg-card"><h3>Decide from evidence</h3><p>Twelve pre-class checks. No full-course dependency until capacity, software, access, support and recovery are demonstrated.</p></article></div></section><section><h2>What is ready—and what is still a decision</h2><div class="pg-grid"><article class="pg-card"><p class="pg-status">Prepared for review</p><h3>Request, plan and evidence</h3><p>Draft form text, two course concepts, a costed staffing model, relative timeline, readiness criteria and the research library.</p>'''+links([('Browse the complete packet','resource-library.html')])+'''</article><article class="pg-card"><p class="pg-status">Not yet confirmed</p><h3>Courses, funding and provider fit</h3><p>Actual titles/term/syllabi, PI and staff appointments, workload/budget approval, CloudBank limits/accounting and every classroom readiness test.</p>'''+links([('Review the twelve checks','readiness.html')])+'''</article></div><p class="pg-refs">Primary request route: '''+refs(['assesscloudbank','pilotaccessprepare','access'])+'''</p></section>'''
    phases=''.join('<article class="pg-phase"><p class="pg-kicker">'+ESC(ph['when'])+'</p><div><h3>'+ESC(ph['title'])+'</h3><p>'+ESC(ph['body'])+'</p><p><strong>Exit evidence:</strong> '+ESC(ph['exit'])+'</p></div></article>' for ph in p['phases'])
    coursecards=''.join('<article class="pg-card" id="course-'+c['id']+'"><p class="pg-kicker">40 planned students · proposed course candidate</p><h3>'+ESC(c['name'])+'</h3><p><strong>Proposed candidate:</strong> <a href="'+ESC(c['public_course_url'],quote=True)+'">'+ESC(c['candidate'])+'</a></p><p class="pg-small">'+ESC(c['selection'])+'</p><p><strong>Core assignment:</strong> '+ESC(c['assignment'])+'</p><p><strong>Inputs:</strong> '+ESC(c['data'])+'</p><p><strong>Environment:</strong> '+ESC(c['tools'])+'</p>'+('<p><strong>Onboarding:</strong> '+ESC(c['onboarding'])+'</p>' if c.get('onboarding') else '')+'<ul>'+''.join('<li>'+ESC(x)+'</li>' for x in c['outcomes'])+'</ul><p><strong>Acceptance:</strong> '+ESC(c['acceptance'])+'</p><details><summary>Representative 15-week activity sequence</summary>'+''.join('<p><strong>'+ESC(w)+':</strong> '+ESC(v)+'</p>' for w,v in c['units'])+'</details><p class="pg-small">'+ESC(c['optional'])+'</p></article>' for c in p['courses'])
    staffing=''.join('<tr><th scope="row" class="pg-role">'+ESC(r['role'])+'</th><td>'+str(r['people'])+'</td><td>'+str(r['hours'])+'</td><td>'+ESC(r['duty'])+'</td></tr>' for r in b['roles'])
    plan='''<p class="pg-kicker">Concrete pilot plan · draft</p><h1>Two courses.<br>One dependable baseline.</h1><p class="pg-lead">Begin with up to ten volunteers and two representative assignments. Move to 80 course seats after the provider, institutional and workload checks pass.</p><p class="pg-note warning">The proposed candidates are INFO 521 and LIS 671. Future offering, instructor consent, term and enrollment are not confirmed here. The schedule is relative to a future approved term. All required activities remain CPU-capable; optional modules and private data need separate approval.</p>'''+links([('Download the pilot brief PDF','pilot-brief.pdf'),('Full plan text','pilot-plan.txt'),('Pre-class checks','readiness.html')])+'''<section id="courses"><h2>What students will do</h2><div class="pg-grid">'''+coursecards+'''</div></section><section><h2>Who does the work</h2><p>Roles can share an appointment where duties and coverage permit, but the primary and backup operators must be distinct. Two course leads and two support TAs are modeled. Appoint actual people and cover their hours before proceeding.</p><div class="pg-table"><table><thead><tr><th>Role</th><th>People</th><th>Added pilot hours</th><th>Responsibility</th></tr></thead><tbody>'''+staffing+'''</tbody></table></div><p class="pg-small">Hours cover the modeled 23-week preparation/teaching/close period. Regular course instruction and grading are excluded; no role is appointed or funded by this table. <a href="budget.html">See rates, funding mode and costs ↗</a>.</p></section><section><h2>Stage the commitment</h2>'''+phases+'''</section><section><h2>Support and continuity in practice</h2><div class="pg-grid"><article class="pg-card"><h3>Help and escalation</h3><p>Two TAs provide six combined help/triage hours per teaching week. The primary operator has four hours/week and the backup one. Publish the real windows once staffing is approved; the proposed first-response target is one staffed business day, with no 24/7 promise.</p><p>TA/course lead → primary operator → backup/provider → service owner. A class-blocking issue triggers the small-data CPU fallback and an assignment accommodation, not an unapproved provider purchase.</p></article><article class="pg-card"><h3>Files, grades and preservation</h3><p>Provider student home → approved independent backup/export destination → restore on another environment. Keep authoritative rosters and grades in approved institutional/LMS systems. Repository deposits contain only rights-cleared, approved public outputs.</p><p>Proposed RPO: 24 hours. Proposed RTO: one business day. Test both; a snapshot or cold archive alone does not establish either.</p></article></div></section><section><h2>How the pilot will be judged</h2><ul>'''+''.join('<li>'+ESC(x)+'</li>' for x in p['evaluation'])+'''</ul><p class="pg-note">Scale only after course leads, operator and sponsor review actual costs, support demand, reliable access and instructional evidence. A working platform or grant award alone does not prove educational benefit.</p></section><p class="pg-refs">Planning evidence: '''+refs(p['source_keys'])+'''</p>'''
    budgetrows=''.join('<tr><th scope="row" class="pg-role">'+ESC(r['role'])+'<span class="pg-small" style="display:block">'+str(r['people'])+' person(s); '+str(r['prep'])+' prep + '+str(r['weekly'])+'/teaching week + '+str(r['close'])+' close hours each</span></th><td><input type="number" name="hours-'+r['id']+'" min="0" max="10000" step="0.5" value="'+str(r['hours'])+'" aria-label="'+ESC(r['role'])+' total pilot hours" required></td><td><input type="number" name="rate-'+r['id']+'" min="0" max="1000" step="0.01" value="'+str(r['rate'])+'" aria-label="'+ESC(r['role'])+' loaded hourly rate in USD" required></td><td><select name="funding-'+r['id']+'" aria-label="'+ESC(r['role'])+' funding mode"><option value="cash"'+(' selected' if r['funding']=='cash' else '')+'>Cash</option><option value="in-kind"'+(' selected' if r['funding']=='in-kind' else '')+'>In-kind</option></select></td><td class="pg-cost" id="cost-'+r['id']+'">$'+f'{r["cost"]:,}'+'</td></tr>' for r in b['roles'])
    reserves=''.join('<tr><th scope="row" class="pg-role">'+ESC(r['item'])+'<span class="pg-small" style="display:block">'+ESC(r['basis'])+'</span></th><td><input type="number" name="cost-'+r['id']+'" min="0" max="1000000" step="1" value="'+str(r['amount'])+'" aria-label="'+ESC(r['item'])+' reserve in USD" required></td></tr>' for r in b['nonlabor'])
    budgetbody='''<p class="pg-kicker">Illustrative USD budget · replaces no institutional quote</p><h1>Resource access is one part of the cost.</h1><p class="pg-lead">Plan for people, support, independent recovery and closure. The default model is $29,736 cash plus $8,220 of required staff-time commitments.</p><p class="pg-note warning">'''+ESC(b['basis'])+'''</p>'''+links([('Default budget CSV','pilot-budget.csv'),('Pilot brief PDF','pilot-brief.pdf')])+'''<form id="budgetForm"><section><h2>Staffing, with visible assumptions</h2><p>Edit total hours, loaded rates and funding modes to compare scenarios. Changes stay in this browser page and do not alter the published defaults, appoint staff or approve funds. Download your scenario if needed.</p><div class="pg-table"><table><thead><tr><th>Role / default effort</th><th>Total hours</th><th>Loaded $/hour</th><th>Funding mode</th><th>Cost</th></tr></thead><tbody>'''+budgetrows+'''</tbody></table></div></section><section><h2>Nonlabor reserves and uncertainty</h2><div class="pg-table"><table><thead><tr><th>Purpose / basis</th><th>USD reserve</th></tr></thead><tbody>'''+reserves+'''</tbody></table></div><div class="pg-controls"><label>Additional provider charges assumption ($)<input type="number" name="quote" min="0" max="1000000" step="1" value="0" required></label><label>Cash contingency (%)<input type="number" name="contingency" min="0" max="100" step="1" value="20" required></label></div><p class="pg-note warning">'''+ESC(b['cloudbank'])+'''</p><div class="pg-actions pg-no-print"><button type="button" id="resetBudget">Reset defaults</button><button type="button" id="downloadBudget">Download current scenario CSV</button></div><p id="budgetError" class="pg-error" role="alert"></p></section></form><section id="budgetResults" aria-live="polite" aria-atomic="true"><h2>Current proposal scenario</h2><div class="pg-metrics"><div><strong id="cashTotal">$29,736</strong><span>Cash with 20% contingency</span></div><div><strong id="inKindTotal">$8,220</strong><span>Required in-kind staff-time commitment</span></div><div><strong id="economicTotal">$37,956</strong><span>Cash + committed staff-time value</span></div></div><p id="budgetSummary"></p><p class="pg-note" id="budgetCeiling"></p><div class="pg-bars" role="figure" aria-label="Proposed resource cost: cash labor, cash reserves and in-kind staff effort">'''+''.join('<div class="pg-bar" id="bar-'+i+'"><div class="pg-bar-label"><span>'+label+'</span><strong class="pg-bar-value"></strong></div><div class="pg-track"><div class="pg-fill '+('inkind' if i=='inKind' else '')+'"></div></div></div>' for i,label in [('cashLabor','Cash labor'),('reserves','Cash nonlabor + contingency'),('inKind','In-kind effort')])+'''</div><noscript><p>The editable budget requires JavaScript. The default CSV and pilot brief contain the complete fixed calculation.</p></noscript></section><section><h2>Release funding in stages</h2><p>Propose a first-stage ceiling of $6,000 for configuration, institutional review and the ten-volunteer canary, within the $30,000 total envelope. This is an authorization cap, not an additional charge or a priced provider test. Release up to the remaining $24,000 only after the readiness evidence is reviewed; cancel/revise if the canary cannot support the core workflows.</p><p>Faculty, Libraries and finance effort is modeled as in-kind. If no written workload commitment is available, switch the corresponding row to Cash and recost; do not assume the labor is available at no cost.</p></section><section><h2>A campus storage comparison, with its limits</h2><p>For eligible open research data only: three TB of campus rental at $47.35/TB/year is <strong>$142.05/year</strong>, charged for the fiscal-year maximum without proration. A separate 2.6 TB active Tier 2 copy would have a modeled 1.6 TB paid overage × $23 × six months = <strong>$220.80</strong>; combined example <strong>$362.85</strong>. Actual classes, billing and data suitability need confirmation.</p><p>'''+ESC(b['storage_example']['boundary'])+'''</p><p class="pg-refs">'''+refs(['pilotuarental','pilotuatier2','pilotuardas','pilotualibbackup'])+'''</p></section><section><h2>What is outside this estimate</h2><p>'''+ESC(b['exclusions'])+'''</p></section>'''
    r=p['request'];rt=request_text(p)
    requestbody='''<p class="pg-kicker">Explore ACCESS · CloudBank Classroom · not submitted</p><h1>A request that can be reviewed before it is sent.</h1><p class="pg-lead">Prepared for the general ACCESS Classroom route. This is a CPU teaching request, separate from an AI-focused NAIRR Classroom proposal or a general commercial-cloud broker award.</p><p class="pg-note warning">Complete course/term/PI fields, final syllabus and CV PDFs, and provider-confirmed resource units before submission. The resource quantity is described concretely below; a numeric CloudBank credit amount cannot be inferred from Jetstream2 SUs.</p>'''+links([('Request PDF','cloudbank-access-request.pdf'),('Copyable request text','cloudbank-access-request.txt'),('Pilot plan','pilot-plan.html')])+'''<section><h2>What the designated PI will need</h2><ul class="pg-checklist">'''+''.join('<li>'+ESC(x)+'</li>' for x in r['attachments'])+'''</ul><p class="pg-refs">Current guidance: '''+refs(['assesscloudbank','pilotaccessprepare'])+'''</p></section><section><h2>Draft form text and resource plan</h2><p>The public overview will be public if submitted through ACCESS; review it accordingly. The field labels below are a drafting aid, not a claim that the live portal has been completed.</p><div class="pg-actions pg-no-print"><button id="copyRequest" type="button">Copy draft request</button></div><p id="copyStatus" class="pg-small" role="status"></p><div class="pg-request" id="requestText">'''+ESC(rt)+'''</div></section><section><h2>Submission remains a human action</h2><p>This site sends nothing to ACCESS or CloudBank. Provider questions are unsent. The designated PI must review the actual portal, award scope and attachments; an approved request must then pass the classroom-readiness checks.</p><p class="pg-refs">'''+refs(r['source_keys'])+'''</p></section>'''
    filters=lambda group,rows,search=False:'<div data-filter-group="'+group+'">'+('<label class="pg-small">Find a topic<input style="display:block;width:100%;padding:10px;font:inherit;margin:10px 0" type="search" aria-label="Search resource library" placeholder="MESA, free hosting, data, evidence…"></label>' if search else '')+'<div class="pg-tabs" role="group" aria-label="Filter '+group+'">'+''.join('<button type="button" data-filter="'+key+'" aria-pressed="'+str(key=='all').lower()+'">'+label+'</button>' for key,label in rows)+'</div><p class="pg-small" data-filter-count aria-live="polite"></p></div>'
    checkcards=''.join('<article class="pg-card" data-filter-item data-category="'+g['category'].lower()+'" id="check-'+g['id']+'"><p class="pg-kicker">'+ESC(g['category']+' · '+g['when'])+'</p><p class="pg-status">'+ESC(g['status'])+'</p><h3>'+str(i+1)+' · '+ESC({'scope':'Scope, owners and funds','provider':'Provider fit and award','accounts':'Login, isolation and removal','software':'Complete CPU assignment','capacity':'Class concurrency','save':'Save, restart and export','grades':'Submission and grade receipts','data':'Data destinations and rights','accessibility':'Accessible essential workflows','recovery':'Independent restore','support':'Support and fallback','exit':'Expiry and teach-out'}[g['id']])+'</h3><p><strong>Owner:</strong> '+ESC(g['owner'])+'</p><p>'+ESC(g['criterion'])+'</p><p><strong>Evidence required:</strong> '+ESC(g['evidence'])+'</p><p><strong>Stop if:</strong> '+ESC(g['stop'])+'</p></article>' for i,g in enumerate(p['checks']))
    readiness='''<p class="pg-kicker">Proposed acceptance register · no checks run</p><h1>Before this becomes required coursework.</h1><p class="pg-lead">Twelve checks, with an accountable owner and concrete evidence. The current status is <strong>0 of 12 confirmed</strong>. An allocation alone does not change that status.</p><p class="pg-note">Targets such as five-minute p95 login, 24-hour RPO and one-business-day recovery/response are proposed acceptance criteria to negotiate and measure. They are not CloudBank guarantees or achieved service levels.</p>'''+links([('Download review register CSV','pilot-readiness.csv'),('Pilot plan','pilot-plan.html'),('Existing route assessment','classroom-assessment.html')])+filters('readinessCards',[('all','All checks'),('access','Access & capacity'),('teaching','Teaching'),('recovery','Recovery & exit'),('operations','Operations')])+'''<div class="pg-grid" id="readinessCards">'''+checkcards+'''</div><section><h2>Who admits the course</h2><p>Each course lead signs off the assignment, accessibility and grading path; the operator and backup sign off access/capacity and recovery; IT/privacy approves data destinations; the service owner and college sponsor verify funding, coverage and remaining risks. Record names, dates and private supporting artifacts in the institutional register, not this public website. Classroom admission requires all applicable checks, or a reviewed substitute that demonstrably meets the same need.</p><p>A failed core check keeps the full course out of the pilot. A failed optional component stays out while the CPU baseline proceeds if its checks passed. Recheck affected gates after image, policy, staffing or provider changes.</p></section>'''
